-- ~/.config/hypr/hyprland.lua
-- Hyprland configuration — Gruvbox Material Dark
-- Generated from hyprlang settings block; verify dispatcher names against
-- /usr/share/hypr/stubs/ if anything behaves unexpectedly.

-- Monitor/workspace config is per-host; generated by Nix into monitors.lua.
-- Returns { primary = "<connector>" } ("" when the host has no pinned primary).
local mon = require("monitors")

-- DMS's Displays page saves to ~/.config/hypr/dms/outputs.lua and runs
-- `hyprctl reload`; without this require the reload restored the Nix layout
-- and every change snapped straight back. DMS also greps this file for
-- "dms.outputs" to decide whether its page is wired up. Loaded after
-- monitors.lua so it wins. pcall: the file is absent until DMS first saves,
-- and a half-written one mustn't take the config down.
pcall(require, "dms.outputs")
-- Host-specific environment variables (NVIDIA etc.) and app choices
-- (terminal/browser), generated by Nix into env.lua
local apps = require("env")

--------------------
---- AUTOSTART -----
--------------------

hl.on("hyprland.start", function()
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP=Hyprland DISPLAY")
    hl.exec_cmd("awww-daemon")
    -- Per-host wallpaper command(s), generated by Nix into wallpaper.lua
    -- (portrait/rotated outputs are fitted instead of crop-zoomed).
    require("wallpaper")
    hl.exec_cmd("playerctld")
    -- nm-applet + syncthingtray + the polkit agent are systemd user services
    -- (modules/home/wm/hyprland.nix); gammastep is one too (HM
    -- services.gammastep) — exec'ing them here starts duplicates.
    -- The shell (DMS: bar, notifications, panels) is NOT exec'd here either:
    -- it is shell-dms.service, started with the graphical session. See
    -- modules/home/wm/dms.nix.

    -- Initial workspace placement for the shared dynamic pool: ws1→primary,
    -- ws2→secondary.
    -- Workspaces stay unbound (freely movable afterwards); this just seeds the
    -- starting layout, overriding Hyprland's per-monitor auto-assignment.
    -- "Focus the workspace, then move the now-active workspace to the target
    -- monitor" is order-independent: it works regardless of which monitor boot
    -- happened to auto-place each ws on. Primary is done last so the cursor
    -- ends up focused there.
    local function place(monName, ws)
        if monName and monName ~= "" then
            hl.dispatch(hl.dsp.focus({ workspace = ws }))
            hl.dispatch(hl.dsp.workspace.move({ monitor = monName }))
        end
    end
    place(mon.secondary, 2)
    place(mon.primary, 1)
end)

-- Tell XWayland which output is primary. Hyprland marks none, and X11 games
-- pick their fullscreen mode from the RANDR primary — with none set they take
-- the first output in the list (here DP-2, a 2160x3840 portrait panel), so the
-- game renders at a portrait resolution and gets letterboxed/stretched into
-- whatever window it actually got. Also re-asserted on layout changes: the flag
-- doesn't survive outputs coming and going (monitor wake, hotplug).
local function setXPrimary()
    if mon.primary ~= "" then
        hl.exec_cmd("xrandr --output " .. mon.primary .. " --primary")
    end
end

hl.on("hyprland.start", setXPrimary)
hl.on("monitor.added", setXPrimary)
hl.on("monitor.removed", setXPrimary)
hl.on("monitor.layout_changed", setXPrimary)

-- wallpaper.lua only reaches the outputs present at login, and awww leaves an
-- output it has never drawn on black — dock monitors connected later stay bare.
-- wallpaper-fill.sh dresses those, then hands the portrait secondary to
-- wallpaper-redress.sh: awww re-attaches that one with the leaves, which
-- silently drops its cheat-sheet. Registered here rather than in the generated
-- wallpaper.lua, which is only required from inside hyprland.start and so
-- wouldn't survive a config reload. Redress checks the output's transform
-- itself, so a landscape secondary on another host is left alone.
hl.on("monitor.added", function()
    hl.exec_cmd("bash ~/.config/hypr/scripts/wallpaper-fill.sh " .. mon.secondary)
end)

-- Hotplug moves every window off (or back onto) the changed output, and each
-- move animates from the old position — windows fly in from where the dock
-- monitors were, with the bezier's overshoot on landing. A flapping USB-C dock
-- repeats that every couple of seconds. Snap instead: animations off here,
-- back on once events have been quiet for a moment (hotplug-calm.sh, which
-- also leaves them off while gaming mode holds them off).
local function calmHotplug()
    hl.config({ animations = { enabled = false } })
    hl.exec_cmd("bash ~/.config/hypr/scripts/hotplug-calm.sh")
end

hl.on("monitor.added", calmHotplug)
hl.on("monitor.removed", calmHotplug)

