---------------------
---- LAYER RULES ----
---------------------

-- DMS popouts, bar pills and plugin popouts (dms:control-center, dms:bar,
-- dms:plugins:plugin…) — DMS can't blur them itself on this Hyprland (no
-- ext-background-effect-v1). Every dms:* layer, since plugin names carry more
-- than one colon; the second rule (later wins) then exempts each popout's
-- full-screen dms:<name>:background click-catcher, which would blur the whole
-- output. 0.5 keeps the blur to the 0.85-alpha panel bodies and pills, not
-- their soft shadows or the empty surface around them.
hl.layer_rule({ match = { namespace = "dms:.*" },                 blur = true,  ignore_alpha = 0.5 })
hl.layer_rule({ match = { namespace = "dms:.*:background" },      blur = false })

---------------------
---- WINDOW RULES ---
---------------------

-- Gaming — allow tearing
-- Match strings are regexes matched against the WHOLE class, so a bare
-- "steam_app_" prefix matches nothing — the ".*" is load-bearing.
hl.window_rule({ match = { class = "steam_app_.*" },                immediate = true })
hl.window_rule({ match = { class = "Minecraft" },                   immediate = true })
-- A gamescope-wrapped session (`gamescope -- steam -bigpicture`, run by hand)
-- reports class "gamescope", not "steam", so the Big Picture rule below never
-- matches it.
-- Without fullscreen it stays a tiled window that Hyprland composites every
-- frame at vsync (major input lag). fullscreen + immediate lets Hyprland
-- direct-scanout the gamescope buffer straight to the display, near-native.
hl.window_rule({ match = { class = "gamescope" },                   fullscreen = true })
hl.window_rule({ match = { class = "gamescope" },                   immediate = true })

-- Games always open on the primary (landscape gaming) monitor. A new window
-- otherwise lands on the focused monitor, so launching from a Steam window
-- parked on the portrait secondary drops the game there — and a fullscreen game
-- can't be dragged off afterwards. `monitor` is a static rule applied at open
-- time, which is also the only safe moment to do this: moving an already
-- fullscreen window between monitors segfaults the compositor.
--
-- Proton reports class "steam_app_<appid>" for the whole Steam library, so one
-- pattern covers it; native ports set their own class and need an entry each.
-- To add one, run `hyprctl clients` while the game is open and copy its class
-- verbatim — these are whole-string regexes, so a prefix alone never matches.
-- Skipped on hosts with no fixed primary (work-laptop, kanshi-owned).
local gameClasses = {
    "steam_app_.*", -- every Proton-launched Steam title
    "gamescope", -- anything run inside a gamescope session
    "Minecraft",
    "TotalWarhammer3", -- native (Feral) build, not Proton
}

if mon.primary ~= "" then
    for _, class in ipairs(gameClasses) do
        hl.window_rule({ match = { class = class }, monitor = mon.primary })
    end
    -- Big Picture launched natively (not under gamescope) — see the rules below.
    hl.window_rule({
        match = { class = "steam", title = "Steam Big Picture Mode" },
        monitor = mon.primary,
    })
end

-- Launchers
-- Big Picture launched natively (no gamescope wrapper): fullscreen + immediate
-- so Hyprland direct-scanouts it (no compositor vsync latency).
hl.window_rule({ match = { class = "steam",   title = "Steam Big Picture Mode" }, fullscreen = true })
hl.window_rule({ match = { class = "steam",   title = "Steam Big Picture Mode" }, immediate = true })
-- Steam dropdown menus are empty-title XWayland popups; without this they
-- steal focus and land on the wrong monitor.
hl.window_rule({ match = { class = "steam", title = "^$" }, no_focus = true })

-- Float
hl.window_rule({ match = { class = "pavucontrol" },        float = true })
hl.window_rule({ match = { class = "nm-connection-editor" }, float = true })
hl.window_rule({ match = { class = "blueman-manager" },    float = true })
hl.window_rule({ match = { title = "Picture-in-Picture" }, float = true })

-- DMS Settings as a dropdown: pinned under the bar at the top right, sliding
-- down out of it. The QML half (no drag/maximise, close once focus leaves DMS)
-- is patched in modules/home/wm/dms.nix. Static rules suffice: DMS
-- destroys the window on close, so every open is a fresh window. y = DMS bar
-- (48) plus its edge gap and a popout-sized gap. The class is DMS's own app
-- id (`//@ pragma AppId` in its shell.qml), not Quickshell's — rule regexes
-- are full matches. The title keeps the rule off Settings' child browsers and
-- pickers, which share the class but carry their own titles.
hl.window_rule({
    name      = "dms-settings-dropdown",
    match     = { class = "com\\.danklinux\\.dms", title = "Settings" },
    float     = true,
    pin       = true,
    move      = "monitor_w-window_w-10 62",
    animation = "slide top",
})

-- Scratchpad — windows on a special workspace float centred with an orange
-- border so they read as scratchpad windows, not tiles. The static fields
-- (float/size/center) only apply to windows that open on the special; the
-- Super+Shift+S bind replicates them for windows moved there. Also used by
-- the per-app scratchpads defined with their binds below.
local function scratchpadRule(name)
    hl.window_rule({
        name  = "scratchpad-style-" .. name,
        -- The workspace matcher needs the "name:" prefix for named specials —
        -- a bare "special:X" parses as an id selector and matches nothing.
        match = { workspace = "name:special:" .. name },

        float        = true,
        size         = "65% 65%",
        center       = true,
        border_color = "rgba(@orange-hex@ee)",
    })
end
scratchpadRule("magic")

-- Opacity
hl.window_rule({ match = { class = "firefox" },      opacity = "1.0 override 1.0 override" })
hl.window_rule({ match = { class = "chromium" },     opacity = "1.0 override 1.0 override" })
hl.window_rule({ match = { class = "google-chrome" },opacity = "1.0 override 1.0 override" })


