-- Workspaces 1–10. Written so DMS's keybind overlay (Super+/) can read them:
-- it parses this file statically, follows a loop only when the key is the
-- bare loop variable, and drops anything concatenated onto a description.
for i = 1, 9 do
    hl.bind(mainMod .. " + " .. i,         hl.dsp.focus({ workspace = i }),       { description = "Switch to workspace" })
    hl.bind(mainMod .. " + SHIFT + " .. i, hl.dsp.window.move({ workspace = i }), { description = "Move window to workspace" })
end
hl.bind(mainMod .. " + 0",         hl.dsp.focus({ workspace = 10 }),       { description = "Switch to workspace 10" })
hl.bind(mainMod .. " + SHIFT + 0", hl.dsp.window.move({ workspace = 10 }), { description = "Move window to workspace 10" })

-- Scroll through workspaces
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }), { description = "Next workspace" })
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }), { description = "Previous workspace" })

-- Move the current workspace (and everything on it) to the monitor left/right.
-- Shared-pool workspaces are unbound, so they carry over and stay put there;
-- focus follows the workspace. ("l"/"r" are direction monitor selectors.)
hl.bind(mainMod .. " + ALT + left",  hl.dsp.workspace.move({ monitor = "l" }), { description = "Move workspace to monitor left" })
hl.bind(mainMod .. " + ALT + right", hl.dsp.workspace.move({ monitor = "r" }), { description = "Move workspace to monitor right" })

-- Scratchpad
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"),             { description = "Toggle scratchpad" })
-- Toggle-move: windows already in a scratchpad go back to the monitor's
-- workspace instead of piling up (the emptied special auto-closes — don't
-- toggle it here, that reopens it). Stashed windows are floated/sized by
-- hand: the scratchpad-style rule's static fields only apply to windows
-- that *open* on the special, not ones moved there. Windows the stash
-- floated are remembered and re-tiled on return; windows that were already
-- floating keep floating. A named function, not an inline one: the overlay
-- shows an inline function's bind as "function()".
local scratchpadFloated = {}
local function stashToScratchpad()
    local win = hl.get_active_window()
    if not win or not win.workspace then return end
    if win.workspace.special then
        local mon = hl.get_active_monitor()
        local target = mon and mon.active_workspace
        if not target then return end
        hl.dispatch(hl.dsp.window.move({ workspace = target.id }))
        if scratchpadFloated[win.address] then
            scratchpadFloated[win.address] = nil
            hl.dispatch(hl.dsp.window.float({ action = "disable" }))
        end
    else
        hl.dispatch(hl.dsp.window.move({ workspace = "special:magic" }))
        local mon = hl.get_active_monitor()
        if mon then
            if not win.floating then scratchpadFloated[win.address] = true end
            -- Monitor width/height are pre-transform; swap for portrait.
            local w, h = mon.width / mon.scale, mon.height / mon.scale
            if mon.transform % 2 == 1 then w, h = h, w end
            hl.dispatch(hl.dsp.window.float({ action = "enable" }))
            hl.dispatch(hl.dsp.window.resize({ x = math.floor(w * 0.65), y = math.floor(h * 0.65), exact = true }))
            hl.dispatch(hl.dsp.window.center())
        end
    end
end
hl.bind(mainMod .. " + SHIFT + S", stashToScratchpad, { description = "Move to/from scratchpad" })

-- Per-app scratchpads — run-or-raise: first press spawns the app into its
-- own special workspace (so the scratchpad-style rule applies at open);
-- afterwards the same key just toggles that special. The query is scoped to
-- the special so a window dragged out to a normal workspace is left alone
-- and a fresh instance spawns.
-- One explicit bind per pad rather than a loop over a table, so the overlay
-- lists them.
local function appScratchpad(name, class, cmd)
    scratchpadRule(name)
    return function()
        if #hl.get_windows({ class = class, workspace = "special:" .. name }) == 0 then
            hl.dispatch(hl.dsp.exec_cmd("[workspace special:" .. name .. "] " .. cmd))
        else
            hl.dispatch(hl.dsp.workspace.toggle_special(name))
        end
    end
end
local termPad = appScratchpad("term", "dropterm", "kitty --class dropterm")
local btopPad = appScratchpad("btop", "btop-drop", "kitty --class btop-drop -e btop")
hl.bind(mainMod .. " + grave",         termPad, { description = "Scratchpad: Terminal" })
hl.bind(mainMod .. " + SHIFT + grave", btopPad, { description = "Scratchpad: btop" })

